sys_ux_data_broker_transform.script:
function transform(input) {
    var idsToInfo = {
        '00f27adb077421102723e7430ad3000f': {
            'url': 'now/adoptionservices/tasks/00f27adb077421102723e7430ad3000f/params/hide-polaris-header/true/control-external-task/true',
            'title': 'sql',
            'productName': 'Microsoft SQL Server',
            'taskId': '82114d270f4d3110ebd9579ac4767ef7',
            'guidedSetupOpenedEvent': 'SQL Server Guided Setup Opened',
        },
        '09668944c347da500ced12f1b4013125': {
            'url': 'now/adoptionservices/tasks/09668944c347da500ced12f1b4013125/params/category-id/ad76890cc307da500ced12f1b40131cd/custom-id/1736248424405',
            'title': 'sql',
            'productName': 'Microsoft SQL Server',
            'taskId': '82114d270f4d3110ebd9579ac4767ef7',
            'guidedSetupOpenedEvent': 'SQL Server Guided Setup Opened',
        },
        'c38e90430f50f910ebd9579ac4767ee4': {
            'url': 'now/adoptionservices/tasks/c38e90430f50f910ebd9579ac4767ee4/params/hide-polaris-header/true/control-external-task/true',
            'title': 'ws',
            'productName': 'Microsoft Windows Server',
            'taskId': 'fb744de70f4d3110ebd9579ac4767e77',
            'guidedSetupOpenedEvent': 'Windows Server Guided Setup Opened',
        }
    };

    var productSetupsData = [];
    var guidanceGr = new GlideRecord('help_guidance');
    //guidanceGr.addQuery('sys_package', '6568aa464d252050f877eb5345401cd5');
    guidanceGr.addEncodedQuery('sys_package.sys_idIN63385cca833912109a4b66d0deaad3f6,6568aa464d252050f877eb5345401cd5');
    guidanceGr.query();
    while (guidanceGr.next()) {
        var guidanceSysId = guidanceGr.getUniqueValue();
        var guidanceDescription = guidanceGr.getValue('description');
        var productSetupObj = {
            productName: idsToInfo[guidanceSysId].productName,
            productSetupDescription: guidanceDescription,
            productSetupUrlFields: {
                url: idsToInfo[guidanceSysId].url,
            },
            productSetupUrlParams: {
                header: idsToInfo[guidanceSysId].title,
                id: idsToInfo[guidanceSysId].title,
            },
            productSetupCategoriesInfo: [],
            productSetupStartedDateStr: 'Not Started',
            productSetupAsssignedToStr: 'Unassigned',
            guidedSetupOpenedEvent: idsToInfo[guidanceSysId].guidedSetupOpenedEvent,
        };

        var userInteractionStepGa = new GlideAggregate('help_user_interaction_step');
        userInteractionStepGa.orderBy('sys_created_on');
        userInteractionStepGa.setLimit(1);
        userInteractionStepGa.query();
        if (userInteractionStepGa.next()) {
            productSetupObj.productSetupStartedDateStr = 'Started on ' + new GlideDateTime(
                userInteractionStepGa.getValue('sys_created_on')
            ).getLocalDate().toString();
        }

        var valueBuilderTaskGr = new GlideRecord('samp_sp_vb_task');
        valueBuilderTaskGr.addNotNullQuery('assigned_to');
        valueBuilderTaskGr.addQuery('sys_id', idsToInfo[guidanceSysId].taskId);
        valueBuilderTaskGr.setLimit(1);
        valueBuilderTaskGr.query();
        if (valueBuilderTaskGr.next()) {
            productSetupObj.productSetupAsssignedToStr = 'Assigned to ' + valueBuilderTaskGr.getDisplayValue('assigned_to');
        }

        var allCategoriesCompleted = true;
        var allCategoriesNotStarted = true;
        var numCategories = 0;
        var numCategoriesCompleted = 0;
        var instanceURL = gs.getProperty('instance_name');
        var categoryGr = new GlideRecord('help_guidance_step');
        categoryGr.addQuery('guidance', guidanceSysId);
        categoryGr.addNullQuery('parent');
        categoryGr.orderBy('order');
        categoryGr.query();
        while (categoryGr.next()) {
            var categoryName = categoryGr.getValue('name');
            var categorySysId = categoryGr.getUniqueValue();
            var categoryColor = null;
            var categoryStatus = null;

            // ONLY counts required steps for now
            var totalCountGa = new GlideAggregate('help_guidance_step');
            totalCountGa.addQuery('parent', categorySysId);
            totalCountGa.addQuery('task_type', 'basic');
            totalCountGa.addAggregate('COUNT');
            totalCountGa.query();
            var totalCount = 0;
            if (totalCountGa.next()) {
                totalCount = totalCountGa.getAggregate('COUNT');
            }

            var completedCountGa = new GlideAggregate('help_user_interaction_step');
            completedCountGa.addQuery('step.parent', categorySysId);
            completedCountGa.addQuery('step.task_type', 'basic');
            completedCountGa.addQuery('status', 'completed');
            completedCountGa.addAggregate('COUNT');
            completedCountGa.query();
            var completedCount = 0;
            if (completedCountGa.next()) {
                completedCount = completedCountGa.getAggregate('COUNT');
            }

            var inProgressCountGa = new GlideAggregate('help_user_interaction_step');
            inProgressCountGa.addQuery('step.parent', categorySysId);
            inProgressCountGa.addQuery('status', 'in_progress');
            inProgressCountGa.addAggregate('COUNT');
            inProgressCountGa.query();
            var inProgressCount = 0;
            if (inProgressCountGa.next()) {
                inProgressCount = inProgressCountGa.getAggregate('COUNT');
            }

            if (totalCount === completedCount) {
                // Completed
                categoryStatus = 'Completed';
                categoryColor = 'positive';
                numCategoriesCompleted += 1;
            } else if (inProgressCount > 0) {
                // In Progress
                categoryStatus = 'In Progress';
                categoryColor = 'warning';
            } else {
                // Not Started
                categoryStatus = 'Not Started';
                categoryColor = 'low';
            }

            var categoryInfo = {
                categoryName: categoryName,
                categoryStatus: categoryStatus,
                categoryColor: categoryColor,
            };
            productSetupObj.productSetupCategoriesInfo.push(categoryInfo);

            if (categoryStatus !== 'Completed') {
                allCategoriesCompleted = false;
            }

            if (categoryStatus !== 'Not Started') {
                allCategoriesNotStarted = false;
            }

            numCategories += 1;
        }

        if (allCategoriesCompleted) {
            productSetupObj.productSetupStatus = 'Completed';
            productSetupObj.buttonTitle = 'Review';
            productSetupObj.productSetupStatusColor = 'positive';
        } else if (allCategoriesNotStarted) {
            productSetupObj.productSetupStatus = 'Not Started';
            productSetupObj.buttonTitle = 'Get Started';
            productSetupObj.productSetupStatusColor = 'low';
        } else {
            productSetupObj.productSetupStatus = 'In Progress';
            productSetupObj.buttonTitle = 'Resume';
            productSetupObj.productSetupStatusColor = 'warning';
        }

        productSetupObj.productSetupStepsCompletionStr = numCategoriesCompleted + ' / ' + numCategories + ' steps completed';
        productSetupsData.push(productSetupObj);
    }
    return productSetupsData;
}
